"use client";

import { useState, useEffect } from "react";
// 1. FIXED: Added Plus and Briefcase to imports
import { 
  X, Trash2, Phone, Star, Edit2, Check, 
  Loader2, MapPin, Plus, Home, Briefcase 
} from "lucide-react";

// --- Types ---
interface Address {
  id: string;
  name: string;
  phone: string;
  altPhone?: string;
  pincode: string;
  addressLine1: string;
  addressLine2?: string;
  city: string;
  district: string;
  state: string;
  type: "Home" | "Work";
  isDefault: boolean;
}

// 2. FIXED: AddressCard and AddressFormModal moved above AddressPage 
// or ensure they are defined in the same file to prevent "Cannot find name"

const FormInput = ({ label, value, onChange, prefix, placeholder }: { 
  label: string; 
  value: string; 
  onChange: (v: string) => void; 
  prefix?: string; 
  placeholder?: string 
}) => (
  <div className="space-y-1 w-full">
    <label className="text-[9px] font-black uppercase tracking-widest text-foreground-subtle ml-1">{label}</label>
    <div className="relative">
      {prefix && <span className="absolute left-3 top-1/2 -translate-y-1/2 text-foreground-subtle text-xs font-bold">{prefix}</span>}
      <input 
        className={`w-full bg-background border border-border rounded-xl py-2.5 text-xs font-bold outline-none focus:border-brand transition-all placeholder:text-foreground-subtle/50 ${prefix ? "pl-10" : "px-3"}`}
        value={value} 
        placeholder={placeholder} 
        onChange={(e) => onChange(e.target.value)} 
      />
    </div>
  </div>
);

const AddressCard = ({ address, onEdit, onDelete }: { 
  address: Address; 
  onEdit: (a: Address) => void; 
  onDelete: (id: string) => void 
}) => (
  <div className={`p-6 rounded-4xl border bg-background-elevated flex flex-col min-h-[260px] transition-all duration-300 ${address.isDefault ? "border-brand ring-1 ring-brand shadow-xl" : "border-border shadow-sm"}`}>
    <div className="flex justify-between items-start mb-6">
      <div className="flex gap-2">
        <span className="px-3 py-1 bg-background-muted text-foreground-muted rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1">
          {address.type === "Home" ? <Home size={10}/> : <Briefcase size={10}/>} {address.type}
        </span>
        {address.isDefault && <span className="px-3 py-1 bg-brand text-brand-foreground rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1"><Star size={10} fill="currentColor" /> Default</span>}
      </div>
      <div className="flex gap-1">
        <button onClick={() => onEdit(address)} className="p-2 hover:bg-background-muted rounded-full text-foreground-subtle hover:text-foreground transition-colors"><Edit2 size={14} /></button>
        <button onClick={() => onDelete(address.id)} className="p-2 hover:bg-destructive/10 rounded-full text-foreground-subtle hover:text-destructive transition-colors"><Trash2 size={14} /></button>
      </div>
    </div>
    
    <div className="grow space-y-1.5">
      <h3 className="font-black text-lg">{address.name}</h3>
      <p className="text-foreground-muted text-xs leading-relaxed line-clamp-2">
        {address.addressLine1}{address.addressLine2 ? `, ${address.addressLine2}` : ""}
      </p>
      <p className="text-foreground font-bold text-xs uppercase tracking-tight">
        {address.city}, {address.district}
      </p>
      <p className="text-foreground-subtle text-[10px] font-black uppercase tracking-widest">
        {address.state} — {address.pincode}
      </p>
      
      <div className="mt-4 flex items-center gap-2 text-[11px] font-black text-foreground bg-background-muted w-fit px-3 py-1.5 rounded-lg border border-border">
        <Phone size={12} className="text-brand" /> <span>+91 {address.phone}</span>
      </div>
    </div>
  </div>
);

const AddressFormModal = ({ initialData, onClose, onSave }: { 
  initialData: Address | null; 
  onClose: () => void; 
  onSave: (data: Address) => void 
}) => {
  const [formData, setFormData] = useState<Partial<Address>>(initialData || { type: "Home", isDefault: false });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (formData.pincode?.length === 6 && !initialData) {
      const fetchRegion = async () => {
        setLoading(true);
        try {
          const res = await fetch(`https://api.postalpincode.in/pincode/${formData.pincode}`);
          const data = await res.json();
          if (data[0].Status === "Success") {
            const details = data[0].PostOffice[0];
            setFormData(prev => ({
              ...prev,
              state: details.State,
              district: details.District,
            }));
          }
        } catch (e) { console.error("Pincode API failed"); }
        finally { setLoading(false); }
      };
      fetchRegion();
    }
  }, [formData.pincode, initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.pincode || !formData.addressLine1 || !formData.name || !formData.phone) {
      alert("Please fill required fields");
      return;
    }
    onSave({ 
      id: initialData?.id || Date.now().toString(), 
      ...formData 
    } as Address);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-background/60 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-background-elevated w-full max-w-lg rounded-4xl shadow-2xl border border-border flex flex-col max-h-[90vh] overflow-hidden">
        <div className="px-6 py-5 border-b border-border flex justify-between items-center sticky top-0 bg-background-elevated">
          <h2 className="text-lg font-black uppercase tracking-tighter">Delivery Address</h2>
          <button onClick={onClose} className="p-2 hover:bg-background-muted rounded-full"><X size={20} /></button>
        </div>

        <div className="p-6 overflow-y-auto space-y-8">
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="relative">
                {/* FIXED: 'v' now has string type via FormInput definition */}
                <FormInput 
                  label="Pincode" 
                  placeholder="6 Digits" 
                  value={formData.pincode || ""} 
                  onChange={(v: string) => setFormData({...formData, pincode: v.replace(/\D/g, "").slice(0,6)})} 
                />
                {loading && <Loader2 className="absolute right-3 bottom-2.5 animate-spin text-brand" size={16} />}
              </div>
              <div className="bg-background-muted rounded-2xl p-2.5 border border-border flex flex-col justify-center">
                <span className="text-[8px] font-black uppercase text-foreground-subtle tracking-widest">Auto-filled Region</span>
                <p className="text-[11px] font-bold truncate">
                  {formData.district ? `${formData.district}, ${formData.state}` : "Enter pincode..."}
                </p>
              </div>
            </div>

            <FormInput 
              label="City / Town" 
              value={formData.city || ""} 
              onChange={(v: string) => setFormData({...formData, city: v})} 
            />
            <FormInput 
              label="House No / Flat No" 
              value={formData.addressLine1 || ""} 
              onChange={(v: string) => setFormData({...formData, addressLine1: v})} 
            />
            <FormInput 
              label="Landmark" 
              value={formData.addressLine2 || ""} 
              onChange={(v: string) => setFormData({...formData, addressLine2: v})} 
            />
          </div>

          <hr className="border-border border-dashed" />

          <div className="space-y-4">
            <FormInput 
              label="Name" 
              value={formData.name || ""} 
              onChange={(v: string) => setFormData({...formData, name: v})} 
            />
            <div className="grid grid-cols-2 gap-4">
              <FormInput 
                label="Phone" 
                prefix="+91" 
                value={formData.phone || ""} 
                onChange={(v: string) => setFormData({...formData, phone: v.replace(/\D/g, "").slice(0,10)})} 
              />
              <FormInput 
                label="Alt Phone" 
                prefix="+91" 
                value={formData.altPhone || ""} 
                onChange={(v: string) => setFormData({...formData, altPhone: v.replace(/\D/g, "").slice(0,10)})} 
              />
            </div>
          </div>
        </div>

        <div className="px-6 py-5 border-t border-border bg-background-muted flex gap-4">
          <button 
            type="button" 
            onClick={handleSubmit} 
            className="flex-1 px-6 py-3.5 rounded-4xl bg-brand text-brand-foreground font-black uppercase text-xs tracking-widest shadow-lg"
          >
            Save Adrress
          </button>
        </div>
      </div>
    </div>
  );
};

export default function AddressPage() {
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAddress, setEditingAddress] = useState<Address | null>(null);

  const handleSave = (data: Address) => {
    let updated = [...addresses];
    if (data.isDefault) updated = updated.map(a => ({ ...a, isDefault: false }));
    const idx = updated.findIndex(a => a.id === data.id);
    idx >= 0 ? (updated[idx] = data) : updated.push(data);
    setAddresses(updated);
    setIsModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground pb-20">
      <main className="max-w-5xl mx-auto px-4 py-12">
        <div className="flex justify-between items-end mb-10 gap-4">
          <h1 className="text-3xl font-black uppercase tracking-tighter">My Addresses</h1>
          <button
            onClick={() => { setEditingAddress(null); setIsModalOpen(true); }}
            className="bg-brand text-brand-foreground px-6 py-3 rounded-4xl font-bold shadow-lg flex items-center gap-2"
          >
            <Plus size={18} /> Add New
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {addresses.map((addr) => (
            <AddressCard 
              key={addr.id} 
              address={addr} 
              onEdit={(a) => { setEditingAddress(a); setIsModalOpen(true); }} 
              onDelete={(id) => setAddresses(addresses.filter(a => a.id !== id))}
            />
          ))}
        </div>
      </main>

      {isModalOpen && (
        <AddressFormModal 
          initialData={editingAddress} 
          onClose={() => setIsModalOpen(false)} 
          onSave={handleSave} 
        />
      )}
    </div>
  );
}